DO $$ DECLARE f record; BEGIN FOR f IN SELECT p.oid::regprocedure AS signature, p.prorettype = 'trigger'::regtype AS is_trigger FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prosecdef LOOP EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM PUBLIC, anon', f.signature); IF f.is_trigger THEN EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM authenticated', f.signature); END IF; END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.start_conversation(_application_id uuid, _body text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE conv uuid; app record; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in to send messages.'; END IF; SELECT a.id,a.applicant_id,a.status,j.owner_id INTO app FROM job_applications a JOIN job_posts j ON j.id=a.job_id WHERE a.id=_application_id; IF app.id IS NULL OR app.owner_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Application not found.'; END IF; IF char_length(btrim(coalesce(_body,'')))=0 OR char_length(_body)>2000 THEN RAISE EXCEPTION 'Message must be 1–2000 characters.'; END IF; SELECT id INTO conv FROM conversations WHERE application_id=_application_id; IF conv IS NULL THEN INSERT INTO conversations(application_id,client_id,applicant_id) VALUES(_application_id,auth.uid(),app.applicant_id) ON CONFLICT(application_id) DO NOTHING RETURNING id INTO conv; IF conv IS NULL THEN SELECT id INTO conv FROM conversations WHERE application_id=_application_id; END IF; END IF; INSERT INTO messages(conversation_id,sender_id,body) VALUES(conv,auth.uid(),_body); IF app.status='pending' THEN UPDATE job_applications SET status='contacted' WHERE id=_application_id; END IF; RETURN conv; END $$;
REVOKE EXECUTE ON FUNCTION public.start_conversation(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.start_conversation(uuid,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.enforce_profile_publish_fields() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.status='published' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM 'published') THEN IF NEW.years_experience IS NULL OR coalesce(cardinality(NEW.past_titles),0)<1 OR coalesce(cardinality(NEW.industries),0)<1 OR coalesce(cardinality(NEW.highlights),0)<3 OR NEW.hours_per_week IS NULL OR NEW.start_availability IS NULL OR coalesce(cardinality(NEW.availability_list),0)<1 OR coalesce(cardinality(NEW.time_zones),0)<1 THEN RAISE EXCEPTION 'Complete your experience, past titles, industries, 3 highlights, availability, weekly hours, start time and working hours before publishing.' USING ERRCODE='check_violation'; END IF; END IF; RETURN NEW; END $$;
REVOKE EXECUTE ON FUNCTION public.enforce_profile_publish_fields() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER enforce_profile_publish_fields BEFORE INSERT OR UPDATE ON public.applicant_profiles FOR EACH ROW EXECUTE FUNCTION public.enforce_profile_publish_fields();